CREATE FUNCTION public.cosine_similarity_192(a real[], b real[]) RETURNS real
    LANGUAGE plpgsql IMMUTABLE
    AS $$
    DECLARE
        dot_product REAL := 0.0;
        i INT;
    BEGIN
        FOR i IN 1..192 LOOP
